import { chromium } from 'playwright-core';
import path from 'node:path';

const stories = [
  { id: 'layout-zimmcountrylanguagemismatch--location', name: 'location' },
  { id: 'layout-zimmcountrylanguagemismatch--language', name: 'language' },
];

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 500, height: 800 } });

for (const story of stories) {
  const url = `http://localhost:6006/iframe.html?id=${story.id}&viewMode=story`;
  await page.goto(url, { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);
  const outPath = path.join('/tmp', `sfcc831_${story.name}.png`);
  await page.screenshot({ path: outPath });
  console.log('Saved', outPath);
}

await browser.close();

